spec.setup_code:
var INK = '#04204B', SEC = '#3D5F91', GUIDE = '#8098BC', BLUE = '#0B4FC0', WARM = '#B4552F', TEAL = '#138374';
var N = 7, PERIOD = 14;
function rng(seed) {
  var s = seed >>> 0;
  return function () {
    s = (s + 0x6D2B79F5) >>> 0;
    var t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
var rand = rng(12345);
var nz = [], bars = [];
for (var a0 = 0; a0 < N; a0++) { nz.push([]); bars.push([]); }
for (var a1 = 0; a1 < N; a1++) {
  for (var b1 = a1; b1 < N; b1++) {
    var nv = rand() * 2 - 1;
    var bb = [rand(), rand(), rand(), rand()];
    nz[a1][b1] = nv; nz[b1][a1] = nv;
    bars[a1][b1] = bb; bars[b1][a1] = bb;
  }
}
var PAIRS = [[0, 3], [2, 6], [1, 4], [5, 0]];
var CI = 1, CJ = 5, KS = [0, 2, 3, 4, 6];
var TOPS = ['Phase 1 · hover over residue pairs (i, j)', 'Phase 2 · triangle update, sweeping k', 'Phase 3 · the whole grid refreshes'];

function clamp(x, a, b) { return x < a ? a : (x > b ? b : x); }
function ease(x) { x = clamp(x, 0, 1); return x * x * (3 - 2 * x); }
function lerp(a, b, t) { return a + (b - a) * t; }
function env(q, f) { return ease(Math.min(q / f, (1 - q) / f, 1)); }
function shade(v) {
  var r = Math.round(lerp(4, 228, v)), g = Math.round(lerp(32, 237, v)), b = Math.round(lerp(75, 249, v));
  return 'rgb(' + r + ',' + g + ',' + b + ')';
}
function wrap(ctx, text, maxW) {
  var words = text.split(' '), lines = [], cur = '';
  for (var i = 0; i < words.length; i++) {
    var test = cur ? cur + ' ' + words[i] : words[i];
    if (ctx.measureText(test).width > maxW && cur) { lines.push(cur); cur = words[i]; } else cur = test;
  }
  if (cur) lines.push(cur);
  return lines;
}
function arrow(ctx, x1, y1, x2, y2, col, f, a) {
  if (f < 0.02) return;
  var ex = x1 + (x2 - x1) * f, ey = y1 + (y2 - y1) * f;
  var ang = Math.atan2(y2 - y1, x2 - x1), hs = 7;
  ctx.save();
  ctx.globalAlpha = a;
  ctx.lineCap = 'round';
  for (var pass = 0; pass < 2; pass++) {
    ctx.strokeStyle = pass === 0 ? '#ffffff' : col;
    ctx.fillStyle = ctx.strokeStyle;
    ctx.lineWidth = pass === 0 ? 5.5 : 2.2;
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(ex, ey); ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(ex + Math.cos(ang) * (pass === 0 ? 2 : 0), ey + Math.sin(ang) * (pass === 0 ? 2 : 0));
    ctx.lineTo(ex - Math.cos(ang - 0.45) * hs, ey - Math.sin(ang - 0.45) * hs);
    ctx.lineTo(ex - Math.cos(ang + 0.45) * hs, ey - Math.sin(ang + 0.45) * hs);
    ctx.closePath(); ctx.fill();
  }
  ctx.restore();
}

return {
  draw: function (ctx, width, height, time, dt) {
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, width, height);
    var T = time % PERIOD;
    var wide = width >= 620;
    var bottom = 342;
    var chX0, chW, chCy, chAmp, gs, gx, gy, hdrY, rad;
    hdrY = 48;
    if (wide) {
      chX0 = 36; chW = width * 0.5 - 36 - 30; chCy = (62 + bottom) / 2; chAmp = 85; rad = 11;
      gs = Math.min(width * 0.5 - 100, 250);
      gx = width * 0.5 + (width * 0.5 - (gs + 70)) / 2 + 18;
      gy = 78 + (bottom - 78 - gs - 8) / 2;
    } else {
      chX0 = 30; chW = width - 60; chCy = 92; chAmp = 22; rad = 9;
      gs = Math.min(width - 100, 176);
      gx = (width - (gs + 70)) / 2 + 18;
      gy = 164;
    }
    var cs = gs / N;
    var gHdrY = wide ? hdrY : 144;
    // residue positions
    var P = [], n, m;
    for (n = 0; n < N; n++) {
      var u = n / 6;
      P.push({ x: chX0 + chW * (u + 0.06 * Math.sin(9 * u)) / 1.03, y: chCy + chAmp * Math.sin(5.2 * u + 0.4) });
    }
    var D = [], maxd = 0;
    for (n = 0; n < N; n++) {
      D.push([]);
      for (m = 0; m < N; m++) {
        var dd = Math.sqrt(Math.pow(P[n].x - P[m].x, 2) + Math.pow(P[n].y - P[m].y, 2));
        D[n][m] = dd; if (dd > maxd) maxd = dd;
      }
    }
    // phase state
    var ph = T < 4 ? 0 : (T < 10 ? 1 : 2);
    var t0 = [0, 4, 10][ph], t1 = [4, 10, 14][ph];
    var capA = ease(Math.min(T - t0, t1 - T) / 0.4);
    var act = null, done = 0;
    var s = 0, q = 0;
    if (ph === 0) {
      s = Math.min(3, Math.floor(T)); q = T - s;
      act = { i: PAIRS[s][0], j: PAIRS[s][1], a: env(q, 0.25) };
    } else if (ph === 1) {
      var t2 = T - 4;
      s = Math.min(4, Math.floor(t2 / 1.2)); q = (t2 - s * 1.2) / 1.2;
      done = s + ease((q - 0.5) / 0.4);
      act = { i: CI, j: CJ, k: KS[s], a: env(q, 0.15) };
    }
    // cell levels and values
    var V = [], errSum = 0, r, c;
    for (r = 0; r < N; r++) {
      V.push([]);
      for (c = 0; c < N; c++) {
        var isIJ = (r === CI && c === CJ) || (r === CJ && c === CI);
        var lv;
        if (T < 1) lv = lerp(0.1, 0.8, ease(T));
        else if (T < 4) lv = 0.8;
        else if (T < 10) lv = isIJ ? 0.8 - 0.45 * done / 5 : 0.8;
        else {
          var e = ease((T - 10 - (r + c) / 12 * 0.6) / 2.2);
          lv = lerp(isIJ ? 0.35 : 0.8, 0.1, e);
        }
        var base = Math.pow(D[r][c] / maxd, 0.85);
        var v = r === c ? 0 : clamp(base + 0.55 * lv * nz[r][c], 0, 1);
        V[r].push(v);
        if (r !== c) errSum += Math.abs(v - base);
      }
    }
    var err = errSum / (N * (N - 1));

    // top caption
    ctx.textAlign = 'center'; ctx.textBaseline = 'alphabetic';
    ctx.font = 'bold 13px sans-serif';
    ctx.globalAlpha = capA; ctx.fillStyle = INK;
    ctx.fillText(TOPS[ph], width / 2, 20);
    ctx.globalAlpha = 1;

    // headers
    ctx.font = '11px sans-serif'; ctx.fillStyle = SEC;
    ctx.textAlign = wide ? 'left' : 'left';
    ctx.fillText('Residues on the chain', chX0 - (wide ? 6 : 0), hdrY);
    ctx.textAlign = 'center';
    ctx.fillText(wide ? 'Pair representation zᵢⱼ (row i, column j)' : 'Pair representation zᵢⱼ (row i, col j)', gx + gs / 2 + (wide ? 0 : 20), gHdrY);

    // backbone
    ctx.strokeStyle = GUIDE; ctx.lineWidth = 2; ctx.beginPath();
    for (var sI = 0; sI <= 60; sI++) {
      var uu = sI / 60;
      var bx = chX0 + chW * (uu + 0.06 * Math.sin(9 * uu)) / 1.03, by = chCy + chAmp * Math.sin(5.2 * uu + 0.4);
      if (sI === 0) ctx.moveTo(bx, by); else ctx.lineTo(bx, by);
    }
    ctx.stroke();

    // chain overlays (lines/triangles)
    var role = [];
    if (act) {
      var pi = P[act.i], pj = P[act.j];
      if (ph === 0) {
        ctx.save(); ctx.globalAlpha = act.a; ctx.strokeStyle = BLUE; ctx.lineWidth = 3;
        ctx.beginPath(); ctx.moveTo(pi.x, pi.y); ctx.lineTo(pj.x, pj.y); ctx.stroke(); ctx.restore();
        role[act.i] = { c: BLUE, t: 'i' }; role[act.j] = { c: BLUE, t: 'j' };
      } else {
        var pk = P[act.k];
        ctx.save(); ctx.globalAlpha = act.a * 0.1; ctx.fillStyle = TEAL;
        ctx.beginPath(); ctx.moveTo(pi.x, pi.y); ctx.lineTo(pj.x, pj.y); ctx.lineTo(pk.x, pk.y); ctx.closePath(); ctx.fill();
        ctx.globalAlpha = act.a; ctx.lineWidth = 3;
        ctx.strokeStyle = BLUE; ctx.beginPath(); ctx.moveTo(pi.x, pi.y); ctx.lineTo(pk.x, pk.y); ctx.stroke();
        ctx.strokeStyle = WARM; ctx.beginPath(); ctx.moveTo(pj.x, pj.y); ctx.lineTo(pk.x, pk.y); ctx.stroke();
        ctx.strokeStyle = INK; ctx.lineWidth = 2; ctx.setLineDash([5, 4]);
        ctx.beginPath(); ctx.moveTo(pi.x, pi.y); ctx.lineTo(pj.x, pj.y); ctx.stroke(); ctx.setLineDash([]);
        ctx.restore();
        role[act.i] = { c: INK, t: 'i' }; role[act.j] = { c: INK, t: 'j' }; role[act.k] = { c: TEAL, t: 'k' };
      }
    }
    // residues
    for (n = 0; n < N; n++) {
      ctx.beginPath(); ctx.arc(P[n].x, P[n].y, rad, 0, 6.2832);
      ctx.fillStyle = '#ffffff'; ctx.fill();
      ctx.strokeStyle = INK; ctx.lineWidth = 1.5; ctx.stroke();
      var hot = role[n] && act.a > 0.5;
      if (role[n]) {
        ctx.save(); ctx.globalAlpha = act.a; ctx.fillStyle = role[n].c;
        ctx.beginPath(); ctx.arc(P[n].x, P[n].y, rad, 0, 6.2832); ctx.fill(); ctx.restore();
      }
      ctx.font = '11px sans-serif'; ctx.textAlign = 'center';
      ctx.fillStyle = hot ? '#ffffff' : INK;
      ctx.fillText('' + (n + 1), P[n].x, P[n].y + 4);
      if (role[n]) {
        ctx.save(); ctx.globalAlpha = act.a; ctx.fillStyle = role[n].c === INK ? INK : role[n].c;
        ctx.font = 'bold 12px sans-serif';
        ctx.fillText(role[n].t, P[n].x, P[n].y - rad - 5); ctx.restore();
      }
    }

    // grid
    for (r = 0; r < N; r++) {
      for (c = 0; c < N; c++) {
        ctx.fillStyle = shade(V[r][c]);
        ctx.fillRect(gx + c * cs + 0.5, gy + r * cs + 0.5, cs - 1, cs - 1);
      }
    }
    ctx.font = '11px sans-serif'; ctx.fillStyle = SEC;
    for (n = 0; n < N; n++) {
      ctx.textAlign = 'center'; ctx.fillText('' + (n + 1), gx + (n + 0.5) * cs, gy - 5);
      ctx.textAlign = 'right'; ctx.fillText('' + (n + 1), gx - 5, gy + (n + 0.5) * cs + 4);
    }
    // legend bar
    var lx = gx + gs + 12, lh = Math.min(gs, 90);
    var grad = ctx.createLinearGradient(0, gy, 0, gy + lh);
    grad.addColorStop(0, shade(0)); grad.addColorStop(1, shade(1));
    ctx.fillStyle = grad; ctx.fillRect(lx, gy, 10, lh);
    ctx.strokeStyle = GUIDE; ctx.lineWidth = 1; ctx.strokeRect(lx + 0.5, gy + 0.5, 9, lh - 1);
    ctx.textAlign = 'left'; ctx.fillStyle = SEC;
    ctx.fillText('near', lx + 15, gy + 10); ctx.fillText('far', lx + 15, gy + lh);

    function cx(c2) { return gx + (c2 + 0.5) * cs; }
    function cy(r2) { return gy + (r2 + 0.5) * cs; }
    function box(r2, c2, col, w, a, dash) {
      ctx.save(); ctx.globalAlpha = a; ctx.strokeStyle = col; ctx.lineWidth = w;
      if (dash) ctx.setLineDash([3, 3]);
      ctx.strokeRect(gx + c2 * cs + 1.5, gy + r2 * cs + 1.5, cs - 3, cs - 3); ctx.restore();
    }
    if (act && ph === 0) {
      box(act.i, act.j, BLUE, 3, act.a, false);
      box(act.j, act.i, BLUE, 1.5, act.a * 0.8, true);
      var bb2 = bars[act.i][act.j];
      ctx.save(); ctx.globalAlpha = act.a; ctx.fillStyle = V[act.i][act.j] < 0.5 ? '#ffffff' : INK;
      for (var bI = 0; bI < 4; bI++) {
        var bh = (0.25 + 0.6 * bb2[bI]) * (cs - 8);
        ctx.fillRect(gx + act.j * cs + 4 + bI * (cs - 8) / 4, gy + act.i * cs + cs - 4 - bh, (cs - 8) / 4 - 1.5, bh);
      }
      ctx.restore();
    } else if (act && ph === 1) {
      var f = ease((q - 0.15) / 0.45);
      box(act.i, act.k, BLUE, 3, act.a, false);
      box(act.j, act.k, WARM, 3, act.a, false);
      box(act.i, act.j, INK, 3, 0.4 + 0.6 * act.a, false);
      box(act.j, act.i, INK, 1.5, 0.5 * act.a, true);
      arrow(ctx, cx(act.k), cy(act.i), cx(act.j), cy(act.i), BLUE, f, act.a);
      arrow(ctx, cx(act.k), cy(act.j), cx(act.j), cy(act.i), WARM, f, act.a);
      ctx.save(); ctx.globalAlpha = act.a; ctx.font = 'bold 11px sans-serif'; ctx.textAlign = 'center';
      ctx.fillStyle = BLUE; ctx.fillText('zᵢₖ', cx(act.k), gy + gs + 14);
      ctx.fillStyle = WARM; ctx.fillText('zⱼₖ', cx(act.k) + (cx(act.k) > gx + gs - 30 ? -26 : 26), gy + gs + 14);
      ctx.restore();
    } else if (ph === 2) {
      var wv = (T - 10) / 2.8;
      if (wv < 1) {
        for (r = 0; r < N; r++) for (c = 0; c < N; c++) {
          var w2 = 1 - Math.abs(wv - (r + c) / 12 * 0.75 - 0.15) * 5;
          if (w2 > 0) box(r, c, TEAL, 2, w2 * 0.8, false);
        }
      }
    }

    // detail caption
    var details = [
      'zᵢⱼ: one feature vector for every pair',
      'if i is near k and k is near j, then i is near j: zᵢⱼ is updated from zᵢₖ and zⱼₖ for every k',
      'every zᵢⱼ is refreshed in parallel and the shading becomes more consistent (mean error ' + err.toFixed(2) + ')'
    ];
    ctx.font = '12px sans-serif'; ctx.textAlign = 'center'; ctx.fillStyle = SEC;
    ctx.globalAlpha = capA;
    var lines = wrap(ctx, details[ph], width - 28);
    for (var li = 0; li < lines.length; li++) ctx.fillText(lines[li], width / 2, bottom + 20 + li * 15);
    ctx.globalAlpha = 1;
    if (ph === 1) {
      ctx.font = '11px sans-serif'; ctx.fillStyle = INK; ctx.textAlign = 'left';
      ctx.fillText('k = ' + (act.k + 1) + '  (step ' + (s + 1) + ' of 5)', wide ? chX0 - 6 : 12, wide ? bottom - 6 : 140);
    }
  }
};
